import type { MetadataRoute } from "next";
import { siteConfig } from "@/config/site";

/**
 * WEB APP MANIFEST (PWA)
 * ---------------------------------------------------------------------------
 * Makes the site "installable" on phones (Add to Home Screen) with the school
 * logo, name, and brand theme colour. 100% free — generated by Next.js, served
 * as /manifest.webmanifest. No service worker / no running cost required for
 * basic install + theming.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: siteConfig.name,
    short_name: siteConfig.shortName,
    description: siteConfig.description,
    start_url: "/",
    display: "standalone",
    background_color: "#152a54",
    theme_color: "#152a54",
    icons: [
      {
        src: siteConfig.logo, // /images/galary/iqr.png
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      {
        src: siteConfig.logo,
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
    ],
  };
}
